// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 sendValue, uint256 blockNum) public {
        sendValue = bound(sendValue, 10 ether, 10 ether);
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(1);
        vm.deal(address(this), sendValue);
        uint256 beforeBal = address(c).balance;
        (bool success, ) = address(c).call{value: sendValue}("");
        if (success) {
            uint256 afterBal = address(c).balance;
            bool shouldClear = (blockNum % 15 == 0);
            if (shouldClear) {
                assertTrue(afterBal == 0);
            } else {
                assertTrue(afterBal == beforeBal + sendValue);
            }
        }
    }
}
